// Build ISC 11 Mathematics ch19 Probability. Run from platform/:
//   npx tsx content/authored/maths/isc-11-mathematics-ch19/src/build.mjs
// ISC 2028 Class XI scope (Unit 5: Statistics and Probability): random experiments, outcomes and sample spaces in set notation;
// events (sure, impossible, simple, compound, mutually exclusive, exhaustive; not, and, or as complement, intersection, union);
// axiomatic probability and its link with classical probability; P(not A), the addition theorem, exactly one, neither, at least one,
// and the three-event extension. Conditional probability, independence, Bayes' theorem and random variables belong to ISC 12.
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, build, chapterTests } from './lib.mjs';
import { V, must } from './vis.mjs';
import { fr, F, choose, subsets, range, Space, addOK, addOK3, COIN3, TETRA2, DIG, CARDS, CARDSP, cardOf, tiles } from './prob.mjs';

setUnit('isc-11-mathematics-ch19');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const r = (s, ...v) => String.raw(s, ...v).replace(/\\n(?![a-z])/g, '\n');
await import('./questions.mjs');
await import('./questions2.mjs');
await import('./questions3.mjs');
await import('./questions4.mjs');

// ---------------------------------------------------------------- numbers quoted in slide text, asserted once more here
{
  must(CARDSP.cnt((id) => cardOf(id)[1] === 'Red') === 3 && CARDSP.cnt((id) => cardOf(id)[2] === 'star') === 4 && CARDSP.cnt((id) => cardOf(id)[1] === 'Red' && cardOf(id)[2] === 'star') === 2 && CARDSP.cnt((id) => cardOf(id)[1] === 'Red' || cardOf(id)[2] === 'star') === 5, 'we3 cards');
  must(DIG.ev((x) => x % 2 === 1).join() === '13,21,23,31,41,43' && DIG.ev((x) => x % 2 === 0 || x > 30).join() === '12,14,24,31,32,34,41,42,43' && 6 + 3 + 2 === 11 && choose(6, 2) - 3 - 1 === 11, 'we4 and we2');
  const o = addOK(DIG, (x) => x % 2 === 0, (x) => x > 30);
  must(o.ok && o.pu.eq(F(3, 4)), 'we7');
  const S40 = new Space(range(1, 40)), Fb = (x) => x <= 24, Ch = (x) => x >= 18 && x <= 35, w = addOK(S40, Fb, Ch);
  must(S40.cnt(Fb) === 24 && S40.cnt(Ch) === 18 && S40.cnt((x) => Fb(x) && Ch(x)) === 7 && w.pu.eq(F(7, 8)) && w.neither.eq(F(1, 8)) && w.exactlyOne.eq(F(7, 10)) && w.ok, 'we5 class of 40: union 35/40 = 7/8, neither 5/40 = 1/8, exactly one 28/40 = 7/10');
  const k = F(9, 10).div(6);
  must(k.eq(F(3, 20)) && k.mul(3).add(k).eq(F(3, 5)) && TETRA2.cnt(([a, b]) => a + b >= 6) === 6 && F(30, 56).eq(F(15, 28)) && F(37, 64).eq(F(1).sub(F(27, 64))), 'we1 we2 we3 we4 of deck 2');
}

// ================================================================ deck 1
const d1 = deck({
  part: 1,
  title: 'Probability - Part 1: Sample spaces and events',
  goals: ['Write the sample space of an experiment in set notation and count its outcomes', 'Decide whether order matters and whether items are returned, and count with products and combinations', 'Describe events as subsets: sure, impossible, simple and compound', 'Build not, and, or events and test whether events are mutually exclusive or exhaustive'],
  slides: [
    sl('title', 'Probability, Part 1', { b: 'From a random experiment to its sample space and its events.', v: V.route1, n: 'Welcome to the chapter on probability. In this first part we write down everything that can happen in a random experiment and call it the sample space. We count its outcomes with products and combinations. Then we treat events as sets, build not, and, or events, and test whether two events are mutually exclusive or exhaustive. Every list and every count in this chapter was checked by computer enumeration.' }),
    sl('concept', 'What you will be able to do', { ul: ['List a **sample space** and count its outcomes', 'Count with **products** and **combinations**', 'Treat an **event** as a subset of the sample space', 'Build **not**, **and**, **or** events', 'Test for **mutually exclusive** and **exhaustive** events'], v: V.goals1, n: 'By the end of this part you will list a sample space and count its outcomes, using products and combinations when the list is long. You will treat an event as a subset of the sample space. You will build the not, and, or events with complements, intersections and unions. And you will test whether two events are mutually exclusive, or exhaustive. The table shows the key result for each skill.' }),
    sl('concept', 'Random experiments and outcomes', { b: 'A **random experiment** has a result we cannot predict for certain, although every possible result is known in advance. Each possible result is an **outcome**.', v: V.expts, n: 'A random experiment is a situation whose result cannot be predicted for certain, although we know every result that could happen. Each possible result is called an outcome. In the table, tossing a coin three times has eight outcomes, rolling a four sided die twice has sixteen, drawing one of twelve tiles has twelve, and switching on two of four lamps has six. Counting outcomes is the first job in every probability problem.' }),
    sl('concept', 'The sample space', { b: r`The set of all outcomes is the **sample space** $S$. Write it in set notation and count its elements with $n(S)$. List each outcome once, and read the experiment carefully before you list.`, m: [r`S = \{\omega_1, \omega_2, \dots, \omega_n\}, \qquad n(S) = n`], v: V.spaces, n: 'The set of all outcomes is the sample space, written S. We write it in set notation, with curly brackets, and count its elements. For a coin tossed twice, with the faces in order, the sample space has four outcomes. For a coin followed by a four sided die it has eight. Read the experiment carefully before you list, and write each outcome exactly once.' }),
    sl('example', 'Worked example 1: a tile and then a coin', { b: r`A bag holds three tiles marked $R_1$, $R_2$ and $G_1$. A tile is drawn and then a coin is tossed. Write the sample space.`, ul: [r`Each of the $3$ tiles can be followed by $\mathrm{H}$ or $\mathrm{T}$`, r`$S = \{(R_1, \mathrm{H}), (R_1, \mathrm{T}), (R_2, \mathrm{H}), (R_2, \mathrm{T}), (G_1, \mathrm{H}), (G_1, \mathrm{T})\}$`, r`$n(S) = 3 \times 2 = 6$`], v: V.tree1, n: 'A tree diagram helps with two stage experiments. The first stage has three branches, one for each tile. Each tile branch splits into heads and tails, so each of the three tiles gives two outcomes. The sample space is the six pairs at the ends of the branches, and the count is three times two, which is six. The product rule counts the ends of a tree without drawing it.' }),
    sl('concept', 'Outcome grids and the product rule', { b: r`For two stages with $n_1$ and $n_2$ results, there are $n_1 \times n_2$ outcomes. A grid shows them all: the first result down the side, the second across the top.`, m: [r`n(S) = n_1 \times n_2`], v: V.grid, n: 'When an experiment has two stages, the number of outcomes is the product of the numbers of results in each stage. For two rolls of a four sided die, that is four times four, sixteen. The grid shows them all: the first score runs down the side, the second score runs across the top, and each cell is one ordered pair. Later, events will be sets of cells in this grid.' }),
    sl('check', 'Quick check: counting outcomes', { b: 'A two-stage experiment: use the product rule.', chk: 'fb1', n: 'Count the results of each stage, then multiply.' }),
    sl('concept', 'Order and return: how many outcomes?', { b: r`Before listing, ask: does the **order** matter, and is an item **returned** before the next draw? A selection made **together** is counted by a combination.`, m: [r`\dbinom{n}{r} = \dfrac{n(n - 1) \cdots (n - r + 1)}{r!}`], v: V.books, n: 'The wording of the experiment decides the sample space. Two books taken together from five: order does not matter, so we count combinations, which gives ten. Two books taken one after the other, none returned, give five times four, twenty ordered pairs. If each book is returned, the pairs number five times five, twenty five. Always decide whether order matters, and whether items are returned.' }),
    sl('example', 'Worked example 2: two tiles from a bag', { b: r`A bag holds $3$ red, $2$ green and $1$ yellow tile. Two tiles are drawn together. Find $n(S)$ and the number of outcomes in which the two tiles have different colours.`, ul: [r`$n(S) = \dbinom{6}{2} = 15$`, r`Same colour: red red $\dbinom{3}{2} = 3$, green green $1$, so $4$ outcomes`, r`Different colours: $15 - 4 = 11$, which is $6 + 3 + 2$ by the table`], v: V.we2, n: 'The two tiles are drawn together, so order does not matter. The sample space has six choose two, which is fifteen, outcomes. Two tiles of the same colour: red red can be chosen in three ways and green green in one way, so four outcomes. The other eleven outcomes have different colours. The table shows the same eleven as six plus three plus two, and the total of fifteen.' }),
    sl('concept', 'Events as subsets', { b: r`An **event** is a subset of the sample space; it **occurs** when the outcome is one of its elements. The whole $S$ is the **sure event**, $\varnothing$ is the **impossible event**, a set with one outcome is a **simple event** and a set with more is a **compound event**.`, v: V.events, n: 'An event is a subset of the sample space. It occurs when the outcome of the experiment is one of its elements. The whole sample space is the sure event, and the empty set is the impossible event. An event with just one outcome is simple, and an event with two or more outcomes is compound. The table shows five events of three coin tosses, with their outcomes listed and counted.' }),
    sl('example', 'Worked example 3: events of a card set', { b: r`An imagined board game has $12$ cards: $2$ red stars, $1$ red moon, $1$ blue star, $2$ blue moons, $1$ blue sun, $1$ green star, $2$ green suns, $1$ yellow moon and $1$ yellow sun. One card is drawn. Let $A$ be "the card is red" and $B$ "the card shows a star".`, ul: [r`$n(A) = 3$ and $n(B) = 4$`, r`$A \cap B$ is the two red stars: $n(A \cap B) = 2$`, r`$n(A \cup B) = 3 + 4 - 2 = 5$`], v: V.we3, n: 'The two way table sorts the twelve cards by colour and shape. Red cards number three, so the event A has three outcomes. Star cards number four, so the event B has four. The cards that are both red and star are the two red stars. The cards that are red or star number three plus four minus two, which is five. We subtract the overlap once because those two cards were counted twice.' }),
    sl('concept', 'Not, and, or', { b: r`Events combine like sets. **Not** is the complement, **and** is the intersection and **or** is the union. "$A$ or $B$" includes the case when both occur.`, m: [r`A' = S \setminus A, \qquad A \cap B, \qquad A \cup B`], v: V.notevents, n: 'Events combine like sets. The event not A is the complement of A: everything in the sample space outside A. The event A and B is the intersection: the outcomes in both. The event A or B is the union: the outcomes in A, or in B, or in both. In the table, tiles one to ten with A even and B more than six give all five combinations, each listed and checked.' }),
    sl('example', 'Worked example 4: events of two-digit numbers', { b: r`Two-digit numbers are written using two different digits from $1, 2, 3, 4$ ($12$ numbers). Let $A$ be "the number is even" and $B$ "the number is more than $30$". List $A'$, $A \cap B$, $A \cup B$ and $A \cap B'$.`, ul: [r`$A' = \{13, 21, 23, 31, 41, 43\}$`, r`$A \cap B = \{32, 34, 42\}$`, r`$A \cup B = \{12, 14, 24, 31, 32, 34, 41, 42, 43\}$, nine numbers`, r`$A \cap B' = \{12, 14, 24\}$`], v: V.we4, n: 'Mark every number for A, the even numbers, and for B, the numbers above thirty. Not A is the six odd numbers. A and B is the three numbers marked in both columns. A or B is every number with at least one mark, nine in all. A but not B is the even numbers that are not above thirty, which are twelve, fourteen and twenty four.' }),
    sl('check', 'Quick check: mutually exclusive or exhaustive', { b: 'Two events with nothing in common: decide whether they must cover the whole sample space.', chk: 'tf1', n: 'Separate the two ideas: no common outcome, and no outcome left out.' }),
    sl('concept', 'Mutually exclusive events', { b: r`Events $A$ and $B$ are **mutually exclusive** when they cannot occur together: they have **no outcome in common**.`, m: [r`A \cap B = \varnothing`], v: V.mex, n: 'Two events are mutually exclusive when they cannot happen together, so they have no outcome in common. Their intersection is the empty set. In the table, less than four and more than nine share no tile. Even and multiple of three share six and twelve, so they are not exclusive. Prime and multiple of four share nothing. At most six and at least six share the tile six.' }),
    sl('concept', 'Exhaustive events', { b: r`Events $E_1, E_2, \dots, E_k$ are **exhaustive** when at least one of them must occur: their **union is the whole sample space**. Events that are both mutually exclusive and exhaustive cut $S$ into separate parts.`, m: [r`E_1 \cup E_2 \cup \dots \cup E_k = S`], v: V.exh, n: 'A set of events is exhaustive when at least one of them must happen, so their union is the whole sample space. To test it, look for outcomes left out. At most six and at least six leave out nothing, so they are exhaustive. Odd and multiple of four leave out two, six and ten. Prime and composite leave out the tile one. Exclusive and exhaustive are separate tests.' }),
    sl('example', 'Worked example 5: both properties', { b: r`For the $12$ two-digit numbers made from two different digits of $1, 2, 3, 4$, decide whether $E_1$: "less than $25$" and $E_2$: "more than $30$" are mutually exclusive and exhaustive.`, ul: [r`$E_1 = \{12, 13, 14, 21, 23, 24\}$, $E_2 = \{31, 32, 34, 41, 42, 43\}$`, r`$E_1 \cap E_2 = \varnothing$: mutually exclusive`, r`$n(E_1) + n(E_2) = 6 + 6 = 12 = n(S)$ with no overlap, so $E_1 \cup E_2 = S$: exhaustive`], v: V.we5, n: 'List each event. Less than twenty five gives six numbers, and more than thirty also gives six. They have nothing in common, so they are mutually exclusive. Their union has six plus six, which is twelve numbers, and that is the whole sample space, so they are also exhaustive. No number lies between twenty four and thirty one, which is why nothing is left out.' }),
    sl('concept', 'Outcomes are not the same as sums', { b: r`Take care to list **outcomes**, not events. The sums $2$ to $8$ of two rolls are **events**, and they are **not equally likely**: the sum $5$ has $4$ of the $16$ pairs, the sum $2$ has only $1$.`, v: V.sums, n: 'Be careful to list outcomes, not events. When two four sided dice are rolled, the sums two to eight are not outcomes, they are events made of several pairs. The bar chart counts the sixteen equally likely pairs behind each sum. The sum five has four pairs, but the sum two has only one. Writing the sample space as the seven sums would hide this, so we always list the pairs.' }),
    sl('example', 'Worked example 6: three coin tosses', { b: r`A coin is tossed three times. Classify each pair of events as mutually exclusive and/or exhaustive: (i) "exactly two heads" and "at least two tails", (ii) "the first toss is a head" and "the first toss is a tail", (iii) "at most one head" and "at least one head".`, ul: [r`(i) no common outcome, union has $7$: exclusive, **not** exhaustive (misses $\mathrm{HHH}$)`, r`(ii) no common outcome, union has $8$: exclusive **and** exhaustive`, r`(iii) three common outcomes, union has $8$: exhaustive, **not** exclusive`], v: V.we6, n: 'For each pair, count the common outcomes and the size of the union. In the first pair nothing is shared and the union has seven outcomes, so they are exclusive but not exhaustive, because all heads is missing. In the second pair nothing is shared and the union is all eight, so they are both. In the third pair three outcomes are shared, so they are not exclusive, but the union is all eight, so they are exhaustive.' }),
    sl('check', 'Quick check: counting outcomes of four tosses', { b: 'Count the outcomes of four tosses with a given number of heads.', chk: 'n1', n: 'Choose which tosses show the heads.' }),
    sl('summary', 'Summary', { ul: [r`Sample space $S$: all outcomes; ask about **order** and **return**`, r`Count with $n_1 \times n_2$ and $\dbinom{n}{r}$`, r`Event: a subset of $S$; sure $= S$, impossible $= \varnothing$`, r`Not $= A'$, and $= A \cap B$, or $= A \cup B$`, r`Exclusive: $A \cap B = \varnothing$. Exhaustive: $A \cup B = S$. Two separate tests`], v: V.sum1, n: 'To sum up. The sample space is the set of all outcomes, and we decide first whether order matters and whether items are returned. We count with products and combinations. An event is a subset of the sample space. Not, and, or are the complement, the intersection and the union. Mutually exclusive means no common outcome, and exhaustive means the union is the whole sample space. They are two separate tests.' }),
    sl('exam-tips', 'Exam tips', { ul: ['State whether order matters and whether items are returned', 'Write events as sets before you count', 'Test mutually exclusive and exhaustive **separately**', 'Use a product or a combination when the list is long'], v: V.tips1, n: 'In the examination, say in a few words whether the order matters and whether items are returned. Write each event as a set before you count anything. Test mutually exclusive and exhaustive separately, because having nothing in common does not mean covering everything. And for a long sample space, count with a product or a combination instead of listing, and keep any list you do write in a tidy order.' }),
  ],
});

// ================================================================ deck 2
const d2 = deck({
  part: 2,
  title: 'Probability - Part 2: Axioms and the addition theorem',
  goals: ['State the axioms of probability and check whether an assignment of probabilities is valid', 'Use classical probability for equally likely outcomes, counting with combinations', 'Use P(not A) = 1 - P(A), including for "at least one"', 'Use the addition theorem for "or", "exactly one" and "neither", with tables, and extend it to three events'],
  slides: [
    sl('title', 'Probability, Part 2', { b: 'Axioms, classical probability, and the rules for not and or.', v: V.route2, n: 'Welcome to the second part on probability. We start from the axioms, the three rules that every probability must obey, and use them to check whether an assignment is valid. Then we meet classical probability for equally likely outcomes, and count with combinations. We find the probability of not an event with the complement rule, and of an or event with the addition theorem. Every probability was computed by exact enumeration.' }),
    sl('concept', 'What you will be able to do', { ul: ['Check a probability assignment with the **axioms**', 'Use **classical** probability and combinations', 'Use the **complement rule**', 'Use the **addition theorem**, **exactly one** and **neither**', 'Extend the theorem to **three events** (optional)'], v: V.goals2, n: 'In this part you will check a probability assignment against the axioms and find unknown probabilities. You will use classical probability for equally likely outcomes, with combinations for selections. You will use the complement rule for not and for at least one. And you will use the addition theorem for or, exactly one and neither, with tables, and extend it to three events as an optional item.' }),
    sl('concept', 'The axioms of probability', { b: r`A probability $P$ on a sample space $S$ gives each event $E$ a number so that three rules hold. Every other rule in this chapter follows from them.`, m: [r`P(E) \ge 0`, r`P(S) = 1`, r`E \cap F = \varnothing \Rightarrow P(E \cup F) = P(E) + P(F)`], v: V.axioms, n: 'The axioms of probability are three rules. First, no event has a negative probability. Second, the whole sample space has probability one, because some outcome is certain. Third, if two events have no outcome in common, the probability of their union is the sum of their probabilities. The table shows each rule on a fair four sided die. Every other rule in this chapter follows from these three.' }),
    sl('concept', 'Assigning probabilities to outcomes', { b: r`In a finite sample space give each outcome a number $P(\omega_i)$. The assignment is **valid** when no number is negative and the numbers **add up to $1$**. The probability of an event is the sum over its outcomes.`, m: [r`P(E) = \sum_{\omega_i \in E} P(\omega_i)`], v: V.assign, n: 'To build a probability model on a finite sample space, give each outcome a number. The assignment is valid when two tests are passed. No number may be negative, and the numbers must add up to exactly one. The table tests five assignments for four outcomes. One has a negative value even though the total is one. Two have a total that is not one. Only the first and the last pass both tests.' }),
    sl('example', 'Worked example 1: finding an unknown', { b: r`A spinner has four outcomes $a, b, c, d$ with probabilities $k$, $2k$, $3k$ and $0.1$. Find $k$ and $P(\{a, c\})$.`, ul: [r`Total $1$: $k + 2k + 3k + 0.1 = 1$, so $6k = 0.9$ and $k = 0.15$`, r`Probabilities $0.15, 0.3, 0.45, 0.1$: all positive`, r`$P(\{a, c\}) = 0.15 + 0.45 = 0.6$`], v: V.we1d2, n: 'The probabilities must add up to one. So k plus two k plus three k plus nought point one equals one. That gives six k equals nought point nine, and k is nought point one five. The four probabilities are nought point one five, nought point three, nought point four five and nought point one, all positive. The event a or c has probability nought point one five plus nought point four five, which is nought point six.' }),
    sl('concept', 'Classical probability', { b: r`If the $n$ outcomes are **equally likely**, the axioms force each to have probability $\dfrac{1}{n}$. An event with $r$ outcomes then has probability $\dfrac{r}{n}$.`, m: [r`P(E) = \dfrac{n(E)}{n(S)}`], ul: [r`$n$ equally likely outcomes with total $1$: each has $\dfrac{1}{n}$`, r`An event of $r$ outcomes: $r \times \dfrac{1}{n} = \dfrac{r}{n}$`], v: V.classical, n: 'When the outcomes are equally likely, the axioms do the work. The n outcomes share a total of one, so each has probability one over n. An event with r outcomes then has r times one over n. That is the classical definition: the number of outcomes in the event, divided by the number of outcomes in the sample space. The table gives three events of two rolls of a four sided die.' }),
    sl('example', 'Worked example 2: a sum of at least six', { b: r`Two fair four-sided dice are rolled together. Find the probability that the sum of the scores is at least $6$.`, ul: [r`Sum $6$: $3$ pairs, sum $7$: $2$ pairs, sum $8$: $1$ pair`, r`$n(E) = 6$ and $n(S) = 16$`, r`$P(E) = \dfrac{6}{16} = \dfrac{3}{8}$`], v: V.we2d2, n: 'List the favourable pairs by sum. Sum six comes from two four, three three, and four two, three pairs. Sum seven comes from three four and four three, two pairs. Sum eight comes only from four four. That makes six favourable pairs out of sixteen equally likely pairs. The probability is six over sixteen, which is three eighths in lowest terms.' }),
    sl('check', 'Quick check: a classical probability', { b: 'Count the favourable pairs of two rolls and divide by $16$.', chk: 'fb3', n: 'Count favourable pairs, then divide by sixteen.' }),
    sl('concept', 'Counting with combinations', { b: r`When items are selected **together**, every selection is equally likely, so $n(S)$ is a combination. For a favourable count, choose from each group and **multiply**.`, v: V.combos, n: 'For selections made together, each selection is equally likely, so the sample space is counted with a combination. A panel of three from eight people has fifty six outcomes, and a committee of four from nine has one hundred and twenty six. To count the favourable selections, choose from each group separately and multiply the results. This avoids listing very long sample spaces.' }),
    sl('example', 'Worked example 3: tiles drawn together', { b: r`A bag holds $5$ red and $3$ white tiles. Three tiles are drawn together at random. Find the probability that exactly two are red.`, ul: [r`$n(S) = \dbinom{8}{3} = 56$`, r`Two red and one white: $\dbinom{5}{2} \times \dbinom{3}{1} = 10 \times 3 = 30$`, r`$P = \dfrac{30}{56} = \dfrac{15}{28}$`], v: V.we3d2, n: 'The three tiles are drawn together, so the sample space has eight choose three, which is fifty six, equally likely outcomes. For exactly two red, choose two of the five red tiles, in ten ways, and one of the three white tiles, in three ways. Multiply to get thirty. The probability is thirty over fifty six, which is fifteen over twenty eight. The table shows all four cases adding up to fifty six.' }),
    sl('concept', 'The complement rule', { b: r`An event $A$ and its complement $A'$ have no outcome in common and together make $S$. By the second and third axioms, $P(A) + P(A') = 1$.`, m: [r`P(A') = 1 - P(A)`], v: V.compl, n: 'An event and its complement have no outcome in common, and together they make the whole sample space. By the axioms their probabilities add up to one. So the probability of not A is one minus the probability of A. This is most useful when the complement is easier to count. The phrase at least one nearly always means that we should count none, and subtract from one. The table shows three examples.' }),
    sl('example', 'Worked example 4: at least one', { b: r`A four-sided die is rolled three times. Find the probability that the score $1$ appears at least once.`, ul: [r`$n(S) = 4 \times 4 \times 4 = 64$`, r`No score $1$: $3 \times 3 \times 3 = 27$`, r`$P(\text{at least one } 1) = 1 - \dfrac{27}{64} = \dfrac{37}{64}$`], v: V.we4d2, n: 'The complement of at least one score one is no score one at all. There are sixty four equally likely outcomes of three rolls. With no score one, each roll has three choices, so there are twenty seven outcomes. The probability of at least one is one minus twenty seven over sixty four, which is thirty seven over sixty four. Counting the thirty seven outcomes directly would take far longer.' }),
    sl('concept', 'The addition theorem', { b: r`$P(A) + P(B)$ counts the outcomes of $A \cap B$ **twice**, so subtract the overlap **once**. When $A$ and $B$ are mutually exclusive the overlap is $0$.`, m: [r`P(A \cup B) = P(A) + P(B) - P(A \cap B)`], v: V.addth, n: 'The probability of A or B is not simply the sum of the two probabilities, because the outcomes in both events are counted twice. So the addition theorem subtracts the overlap once. When the events are mutually exclusive, the overlap is empty, and the probabilities simply add. The table sorts a class of forty pupils into four regions: football only, both, chess only, and neither.' }),
    sl('example', 'Worked example 5: football and chess', { b: r`In a class of $40$, $24$ play football, $18$ play chess and $7$ play both. A pupil is chosen at random. Find the probability that the pupil plays (i) football or chess, (ii) neither, (iii) exactly one of the two.`, ul: [r`(i) $\dfrac{24}{40} + \dfrac{18}{40} - \dfrac{7}{40} = \dfrac{35}{40} = \dfrac{7}{8}$`, r`(ii) $1 - \dfrac{7}{8} = \dfrac{1}{8}$`, r`(iii) $\dfrac{35 - 7}{40} = \dfrac{28}{40} = \dfrac{7}{10}$`], v: V.we5d2, n: 'Use the addition theorem for the first part. Twenty four plus eighteen minus seven, all over forty, is thirty five over forty, which is seven eighths. Neither is the complement, one eighth. Exactly one means the union without the overlap, so thirty five minus seven, which is twenty eight, over forty, or seven tenths. The bar chart shows the four regions, which add up to one.' }),
    sl('check', 'Quick check: the union and the sum', { b: 'Compare the probability of a union with the sum of the two probabilities.', chk: 'tf3', n: 'Which is larger, the union or the sum? Use the addition theorem.' }),
    sl('concept', 'Exactly one, neither, at least one', { b: r`Every phrase is a rearrangement of the addition theorem and the complement rule. Name the phrase first, then pick its formula.`, v: V.special, n: 'Several common phrases are rearrangements of the addition theorem. At least one means the union. Neither is one minus the union. Exactly one is the sum of the two probabilities minus twice the overlap, because the overlap must be removed from each event. When the events are mutually exclusive, the union is just the sum. The table gives each formula with a worked value.' }),
    sl('example', 'Worked example 6: two subjects', { b: r`A student passes mathematics with probability $0.7$, physics with probability $0.6$, and at least one of the two with probability $0.9$. Find the probability of passing both, and of passing mathematics only.`, ul: [r`$P(\text{both}) = 0.7 + 0.6 - 0.9 = 0.4$`, r`Mathematics only: $0.7 - 0.4 = 0.3$`, r`Physics only $0.2$, neither $0.1$: the four regions add up to $1$`], v: V.we6d2, n: 'The given probability of at least one is the union. Rearrange the addition theorem to find the overlap: nought point seven plus nought point six minus nought point nine, which is nought point four. Passing mathematics only is the mathematics probability minus the overlap, nought point three. Physics only is nought point two, and neither is one minus nought point nine, which is nought point one. The four regions add up to one.' }),
    sl('check', 'Quick check: neither', { b: 'Count those who bought at least one item, then use the complement.', chk: 'n5', n: 'Find the number in the union first, then subtract from the total.' }),
    sl('example', 'Worked example 7: two routes, one answer', { b: r`For the $12$ two-digit numbers from two different digits of $1, 2, 3, 4$, let $A$ be "even" and $B$ "more than $30$". Find $P(A \cup B)$ by counting and by the addition theorem.`, ul: [r`Counting: $9$ numbers in $A \cup B$, so $\dfrac{9}{12} = \dfrac{3}{4}$`, r`Theorem: $\dfrac{6}{12} + \dfrac{6}{12} - \dfrac{3}{12} = \dfrac{9}{12} = \dfrac{3}{4}$`], v: V.we7d2, n: 'This example checks the addition theorem against direct counting. Counting the union directly gives nine numbers out of twelve, which is three quarters. The theorem gives six twelfths plus six twelfths minus three twelfths. The overlap of three is the numbers thirty two, thirty four and forty two. Both routes give nine twelfths, which is three quarters. It is good practice to check a theorem answer by counting whenever the sample space is small.' }),
    sl('concept', 'Three events (optional extension)', { b: r`For three events add the singles, subtract the three pair overlaps, and add back the triple overlap, which was removed once too often.`, m: [r`P(A \cup B \cup C) = P(A) + P(B) + P(C) - P(A \cap B) - P(A \cap C) - P(B \cap C) + P(A \cap B \cap C)`], v: V.three, n: 'This is an optional extension. For three events, first add the three single probabilities. Each pair overlap has now been counted twice, so subtract the three pair overlaps. But the outcomes in all three events were added three times and subtracted three times, so they are now missing altogether. Add the triple overlap back once. The pattern is add, subtract, add back.' }),
    sl('example', 'Worked example 8: three events', { b: r`A tile is drawn from tiles numbered $1$ to $30$. Let $A$, $B$, $C$ be "a multiple of $2$", "of $3$" and "of $5$". Find $P(A \cup B \cup C)$.`, ul: [r`Singles: $15, 10, 6$; pairs (multiples of $6, 10, 15$): $5, 3, 2$; triple (multiples of $30$): $1$`, r`$n(A \cup B \cup C) = 15 + 10 + 6 - 5 - 3 - 2 + 1 = 22$`, r`$P = \dfrac{22}{30} = \dfrac{11}{15}$`], v: V.we8d2, n: 'Count each term. Multiples of two, three and five number fifteen, ten and six. The pair overlaps are the multiples of six, ten and fifteen, which number five, three and two. The triple overlap is the multiples of thirty, just one tile. The union is fifteen plus ten plus six, minus five, three and two, plus one, which is twenty two. The probability is twenty two over thirty, or eleven over fifteen.' }),
    sl('summary', 'Summary', { ul: [r`Axioms: $P(E) \ge 0$, $P(S) = 1$, additive for exclusive events`, 'A valid assignment has no negative value and total $1$', r`Equally likely: $P(E) = \dfrac{n(E)}{n(S)}$; use combinations for selections`, r`$P(A') = 1 - P(A)$; "at least one" $= 1 - P(\text{none})$`, r`$P(A \cup B) = P(A) + P(B) - P(A \cap B)$; neither $= 1 - P(A \cup B)$`], v: V.sum2, n: 'To sum up. The three axioms are the foundation. A valid assignment has no negative value and a total of one. With equally likely outcomes, the probability of an event is the number of favourable outcomes over the number of outcomes, and we use combinations for selections. The complement rule gives not, and at least one. The addition theorem gives or, and with the complement it gives neither and exactly one.' }),
    sl('exam-tips', 'Exam tips', { ul: ['Write the formula first, then substitute the values', 'Every probability lies between $0$ and $1$: check your answer', 'For "at least one", subtract the complement from $1$', 'Give fractions in lowest terms'], v: V.tips2, n: 'In the examination, write the formula first and substitute afterwards, because the method marks are for the formula and the substitution. Check that every answer lies between zero and one. For at least one, count the complement. Give fractions in lowest terms, or decimals when the data are decimals. For an exactly one question, remember to subtract the overlap twice, once from each event.' }),
  ],
});

// ================================================================ notes
const notes = {
  unit: 'isc-11-mathematics-ch19', version: 1, title: 'Probability - chapter notes', language: 'en',
  sections: [
    { heading: '1. Random experiments and sample spaces', body_md: r`A **random experiment** has a result that cannot be predicted for certain, although all possible results are known. Each possible result is an **outcome**, and the set of all outcomes is the **sample space** $S$, written in set notation, for example $S = \{\mathrm{H}, \mathrm{T}\}$ for one toss of a coin. The number of outcomes is $n(S)$.\n\nRead the experiment before listing. For two rolls of a four-sided die with the scores in order, $S$ has $16$ ordered pairs, and $(1, 2)$ and $(2, 1)$ are different outcomes. A list of sums, such as $2, 3, \dots, 8$, is a list of events, not a sample space of equally likely outcomes.`, key_terms: [{ term: 'Random experiment', definition_md: 'An experiment whose result cannot be predicted for certain, with all possible results known in advance.' }, { term: 'Outcome', definition_md: 'One possible result of the experiment.' }, { term: 'Sample space', definition_md: r`The set $S$ of all outcomes; $n(S)$ is its number of elements.` }], formulas: [{ latex: r`S = \{\omega_1, \omega_2, \dots, \omega_n\}`, label: 'Sample space' }], visual: V.spaces, visuals: [V.expts, V.sums], topic_ids: [topic(1)] },
    { heading: '2. Counting the outcomes', body_md: r`For two stages with $n_1$ and $n_2$ results there are $n_1 \times n_2$ outcomes; for more stages multiply again. A tree diagram or an outcome grid shows them.\n\nTwo questions decide the sample space: does the **order** matter, and is an item **returned**? Two books from five give $5 \times 4 = 20$ ordered pairs (none returned), $5 \times 5 = 25$ (returned), and $\dbinom{5}{2} = 10$ when taken together. A selection made together is counted with the combination $\dbinom{n}{r}$, and the favourable selections are found by choosing from each group and multiplying.`, key_terms: [{ term: 'Product rule', definition_md: r`Stages with $n_1$, $n_2$, $\dots$ results give $n_1 \times n_2 \times \cdots$ outcomes.` }, { term: 'Combination', definition_md: r`$\dbinom{n}{r}$, the number of selections of $r$ items from $n$ when order does not matter.` }], formulas: [{ latex: r`n(S) = n_1 \times n_2`, label: 'Two stages' }, { latex: r`\dbinom{n}{r} = \dfrac{n(n - 1) \cdots (n - r + 1)}{r!}`, label: 'Combination' }], visual: V.grid, visuals: [V.tree1, V.books, V.we2], topic_ids: [topic(1)] },
    { heading: '3. Events and the language of sets', body_md: r`An **event** is a subset of $S$ and it **occurs** when the outcome belongs to it. The whole $S$ is the **sure event**; $\varnothing$ is the **impossible event**; an event with one outcome is **simple** and one with more is **compound**.\n\nThe words **not**, **and**, **or** are the complement, intersection and union: $A'$, $A \cap B$, $A \cup B$. "$A$ or $B$" includes the case in which both occur. "$A$ but not $B$" is $A \cap B'$, "neither" is $(A \cup B)' = A' \cap B'$, "not both" is $(A \cap B)' = A' \cup B'$, and "exactly one" is $(A \cap B') \cup (A' \cap B)$.`, key_terms: [{ term: 'Event', definition_md: 'A subset of the sample space.' }, { term: 'Simple and compound events', definition_md: 'An event with exactly one outcome is simple; an event with more than one is compound.' }], formulas: [{ latex: r`A', \quad A \cap B, \quad A \cup B`, label: 'Not, and, or' }, { latex: r`(A \cup B)' = A' \cap B', \quad (A \cap B)' = A' \cup B'`, label: 'Complements of or and and' }], visual: V.events, visuals: [V.notevents, V.we3, V.we4], topic_ids: [topic(2)] },
    { heading: '4. Mutually exclusive and exhaustive events', body_md: r`Events $A$ and $B$ are **mutually exclusive** when $A \cap B = \varnothing$: they cannot occur together. Events $E_1, \dots, E_k$ are **exhaustive** when $E_1 \cup \dots \cup E_k = S$: at least one must occur. Events that are both cut $S$ into separate parts; an event and its complement always do.\n\nThe two properties are tested separately. Check the common outcomes for the first and the outcomes left out for the second. "At most one head" and "at least two heads" are both; "exactly two heads" and "at least two tails" are exclusive but leave out $\mathrm{HHH}$.`, key_terms: [{ term: 'Mutually exclusive', definition_md: r`Having no outcome in common: $A \cap B = \varnothing$.` }, { term: 'Exhaustive', definition_md: r`Having a union equal to $S$: no outcome is left out.` }], formulas: [{ latex: r`A \cap B = \varnothing`, label: 'Mutually exclusive' }, { latex: r`E_1 \cup E_2 \cup \dots \cup E_k = S`, label: 'Exhaustive' }], visual: V.mex, visuals: [V.exh, V.we5, V.we6], topic_ids: [topic(2)] },
    { heading: '5. The axioms and valid assignments', body_md: r`A probability $P$ on a finite sample space satisfies three **axioms**: $P(E) \ge 0$; $P(S) = 1$; and $P(E \cup F) = P(E) + P(F)$ whenever $E \cap F = \varnothing$. Everything else follows from them.\n\nIn a finite sample space an assignment $P(\omega_i)$ to the outcomes is **valid** when no value is negative and the values **add up to $1$**; the probability of an event is the sum over its outcomes. A list that adds up to $1$ but contains a negative value is not valid, and neither is one with a total other than $1$. An unknown such as $k$ is found by setting the total equal to $1$.`, key_terms: [{ term: 'Axioms of probability', definition_md: r`$P(E) \ge 0$, $P(S) = 1$, and additivity for events with no common outcome.` }, { term: 'Valid assignment', definition_md: 'Probabilities of outcomes that are all at least $0$ and add up to $1$.' }], formulas: [{ latex: r`P(E) \ge 0, \quad P(S) = 1`, label: 'First two axioms' }, { latex: r`P(E) = \sum_{\omega_i \in E} P(\omega_i)`, label: 'Probability of an event' }], visual: V.axioms, visuals: [V.assign, V.we1d2], topic_ids: [topic(3)] },
    { heading: '6. Classical probability and counting', body_md: r`If the $n$ outcomes are equally likely the axioms give each one probability $\dfrac{1}{n}$, so an event with $r$ outcomes has probability $\dfrac{r}{n}$: the **classical** definition $P(E) = \dfrac{n(E)}{n(S)}$. Use it only when the outcomes really are equally likely.\n\nFor selections made together, $n(S)$ is a combination and the favourable count multiplies the choices from each group: exactly two red from $5$ red and $3$ white tiles, three drawn, is $\dfrac{\dbinom{5}{2}\dbinom{3}{1}}{\dbinom{8}{3}} = \dfrac{30}{56}$. When the outcomes are not equally likely (a loaded die) add the given probabilities of the outcomes of the event.`, key_terms: [{ term: 'Classical probability', definition_md: 'The ratio of favourable outcomes to all outcomes when the outcomes are equally likely.' }, { term: 'Equally likely outcomes', definition_md: 'Outcomes with the same probability, each $\\dfrac{1}{n}$ for $n$ outcomes.' }], formulas: [{ latex: r`P(E) = \dfrac{n(E)}{n(S)}`, label: 'Classical probability' }], visual: V.classical, visuals: [V.we2d2, V.combos, V.we3d2], topic_ids: [topic(3)] },
    { heading: '7. The complement and the addition theorem', body_md: r`Because $A$ and $A'$ are disjoint with union $S$, $P(A) + P(A') = 1$, so $P(A') = 1 - P(A)$. For "at least one", count the case "none" and subtract from $1$.\n\nThe **addition theorem** is $P(A \cup B) = P(A) + P(B) - P(A \cap B)$: the overlap is counted twice in the sum and is removed once. For mutually exclusive events it reduces to $P(A) + P(B)$. A table of the four regions (both, $A$ only, $B$ only, neither) makes problems easy to read, and the theorem can be checked by counting the union.`, key_terms: [{ term: 'Complement rule', definition_md: r`$P(A') = 1 - P(A)$.` }, { term: 'Addition theorem', definition_md: r`$P(A \cup B) = P(A) + P(B) - P(A \cap B)$.` }], formulas: [{ latex: r`P(A') = 1 - P(A)`, label: 'Complement' }, { latex: r`P(A \cup B) = P(A) + P(B) - P(A \cap B)`, label: 'Addition theorem' }], visual: V.compl, visuals: [V.we4d2, V.addth, V.we5d2], topic_ids: [topic(4)] },
    { heading: '8. Exactly one, neither, and three events', body_md: r`From the theorem: **neither** is $P(A' \cap B') = 1 - P(A \cup B)$; **exactly one** is $P(A) + P(B) - 2P(A \cap B)$; "$A$ but not $B$" is $P(A) - P(A \cap B)$; "not both" is $1 - P(A \cap B)$.\n\n**Optional extension (three events):** $P(A \cup B \cup C) = P(A) + P(B) + P(C) - P(A \cap B) - P(A \cap C) - P(B \cap C) + P(A \cap B \cap C)$. Add the singles, subtract the pair overlaps, add back the triple overlap. Conditional probability and independence are not part of this chapter.`, key_terms: [{ term: 'Exactly one', definition_md: r`$A$ or $B$ occurs but not both: $P(A) + P(B) - 2P(A \cap B)$.` }, { term: 'Neither', definition_md: r`Neither event occurs: $1 - P(A \cup B)$.` }], formulas: [{ latex: r`P(A) + P(B) - 2P(A \cap B)`, label: 'Exactly one' }, { latex: r`1 - P(A \cup B)`, label: 'Neither' }], visual: V.special, visuals: [V.we6d2, V.three, V.we8d2], topic_ids: [topic(4)] },
  ],
  exam_tips_md: r`**How ISC marks are usually awarded**\n- *Sample space and events (1-2 marks):* the set written in brackets with every outcome, then the count or the event as a set.\n- *Mutually exclusive or exhaustive (2 marks):* the common outcomes, the union, and a conclusion for each property separately.\n- *Axioms and assignments (2-3 marks):* the total, the sign of every value, and the verdict with the reason.\n- *Classical probability (2-3 marks):* $n(S)$, $n(E)$ (with a combination when items are drawn together), and the fraction in lowest terms.\n- *Addition theorem (3 marks):* the formula, the substitution, the answer; then neither or exactly one from the complement.\n- *Long questions (5 marks, in parts):* the sample space first, then each event as a set, then the probabilities, and a second route (counting) as a check.\n\n**Common mistakes**\n- Writing $P(A \cup B) = P(A) + P(B)$ when the events overlap.\n- Treating "no common outcome" as "covers the sample space".\n- Using $\dfrac{1}{n}$ for outcomes that are not equally likely, or listing the sums of two dice as outcomes.\n- Counting ordered selections when the items are drawn together (or the reverse).\n- Accepting a list of probabilities that adds up to $1$ but contains a negative value.\n- Answers outside $0 \le P \le 1$, or fractions not in lowest terms.`,
  status: 'draft', provenance: d1.provenance,
};

const fc = (id, front_md, back_md, tag, t) => ({ id, front_md, back_md, tag, topic_id: topic(t) });
const flashcards = {
  unit: 'isc-11-mathematics-ch19', version: 1, language: 'en',
  cards: [
    fc('f01', 'What is a random experiment?', 'An experiment whose result cannot be predicted for certain, although all possible results are known in advance.', 'definition', 1),
    fc('f02', 'What is an outcome, and what is the sample space?', 'An outcome is one possible result; the sample space $S$ is the set of all outcomes, and $n(S)$ is their number.', 'definition', 1),
    fc('f03', 'Sample space of tossing a coin twice, faces in order', '$S = \\{\\mathrm{HH}, \\mathrm{HT}, \\mathrm{TH}, \\mathrm{TT}\\}$, with $n(S) = 4$.', 'concept', 1),
    fc('f04', 'Number of outcomes of two stages with $n_1$ and $n_2$ results', '$n_1 \\times n_2$ (the product rule).', 'formula', 1),
    fc('f05', 'Two questions to ask before listing outcomes', 'Does the order matter? Is each item returned before the next draw?', 'exam-tip', 1),
    fc('f06', 'Number of selections of $r$ items from $n$ taken together', '$\\dbinom{n}{r} = \\dfrac{n(n - 1) \\cdots (n - r + 1)}{r!}$.', 'formula', 1),
    fc('f07', 'Why are the sums $2, 3, \\dots, 8$ of two four-sided dice not equally likely?', 'They are events of the $16$ equally likely pairs; the sum $5$ has $4$ pairs, the sum $2$ has $1$.', 'concept', 1),
    fc('f08', 'Define an event.', 'A subset of the sample space; it occurs when the outcome is one of its elements.', 'definition', 2),
    fc('f09', 'Sure event and impossible event', 'The sure event is $S$ itself; the impossible event is $\\varnothing$.', 'definition', 2),
    fc('f10', 'Simple event and compound event', 'A simple event has exactly one outcome; a compound event has more than one.', 'definition', 2),
    fc('f11', 'Set symbols for the events not $A$, $A$ and $B$, $A$ or $B$', "$A'$, $A \\cap B$ and $A \\cup B$ (the union includes the case of both).", 'formula', 2),
    fc('f12', 'Set symbol for "$A$ occurs but $B$ does not"', "$A \\cap B'$.", 'formula', 2),
    fc('f13', 'Set symbol for "neither $A$ nor $B$"', "$(A \\cup B)' = A' \\cap B'$.", 'formula', 2),
    fc('f14', 'Set symbol for "exactly one of $A$ and $B$"', "$(A \\cap B') \\cup (A' \\cap B)$.", 'formula', 2),
    fc('f15', 'When are two events mutually exclusive?', 'When they cannot occur together: $A \\cap B = \\varnothing$.', 'definition', 2),
    fc('f16', 'When are events $E_1, \\dots, E_k$ exhaustive?', 'When at least one must occur: $E_1 \\cup \\dots \\cup E_k = S$.', 'definition', 2),
    fc('f17', 'Does "no common outcome" mean the events are exhaustive?', 'No. Mutually exclusive and exhaustive are separate tests; test each one on its own.', 'exam-tip', 2),
    fc('f18', 'Which events are always both mutually exclusive and exhaustive?', "An event $A$ and its complement $A'$.", 'concept', 2),
    fc('f19', 'State the three axioms of probability.', '$P(E) \\ge 0$; $P(S) = 1$; $P(E \\cup F) = P(E) + P(F)$ when $E \\cap F = \\varnothing$.', 'formula', 3),
    fc('f20', 'When is an assignment of probabilities to the outcomes valid?', 'When no value is negative and the values add up to $1$.', 'concept', 3),
    fc('f21', 'Probability of an event in a finite sample space', 'The sum of the probabilities of the outcomes in the event.', 'concept', 3),
    fc('f22', 'How do you find an unknown such as $k$ in an assignment?', 'Set the total of all the probabilities equal to $1$ and solve; then check that no value is negative.', 'exam-tip', 3),
    fc('f23', 'Classical probability for equally likely outcomes', '$P(E) = \\dfrac{n(E)}{n(S)}$; each of $n$ outcomes has probability $\\dfrac{1}{n}$.', 'formula', 3),
    fc('f24', 'Favourable count for items drawn together from two groups', 'Choose from each group and multiply the combinations, for example $\\dbinom{5}{2} \\times \\dbinom{3}{1}$.', 'concept', 3),
    fc('f25', 'Rule for the probability of "not $A$"', "$P(A') = 1 - P(A)$.", 'formula', 4),
    fc('f26', 'How do you find the probability of "at least one"?', 'Find the probability of "none" and subtract it from $1$.', 'exam-tip', 4),
    fc('f27', 'State the addition theorem.', '$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$.', 'formula', 4),
    fc('f28', 'Addition theorem for mutually exclusive events', '$P(A \\cup B) = P(A) + P(B)$, because $P(A \\cap B) = 0$.', 'formula', 4),
    fc('f29', 'Probability that neither $A$ nor $B$ occurs', "$P(A' \\cap B') = 1 - P(A \\cup B)$.", 'formula', 4),
    fc('f30', 'Probability that exactly one of $A$ and $B$ occurs', '$P(A) + P(B) - 2P(A \\cap B)$.', 'formula', 4),
    fc('f31', 'Probability that $A$ occurs but $B$ does not', '$P(A \\cap B\') = P(A) - P(A \\cap B)$.', 'formula', 4),
    fc('f32', 'Three-event addition theorem (optional)', '$P(A \\cup B \\cup C) = \\sum P(A) - \\sum P(A \\cap B) + P(A \\cap B \\cap C)$.', 'formula', 4),
  ],
};

